mapper.select:
select u.user_id as userId, u.user_name as userName, u.nick_name as nickName, u.status as status, u.create_time as createTime, exists (select 1 from sys_user_role ur2 join sys_role r2 on r2.role_id = ur2.role_id where ur2.user_id = u.user_id and r2.role_key = 'admin' and r2.del_flag = '0') as isBoss, (select count(*) from jiedan_order o where o.owner_id = u.user_id and o.del_flag = 0) as orderCount, (select count(*) from jiedan_order o where o.owner_id = u.user_id and o.del_flag = 0 and o.status not in ('done', 'cancelled')) as unfinishedCount from sys_user u where u.del_flag = '0' and exists (select 1 from sys_user_role ur join sys_role r on r.role_id = ur.role_id where ur.user_id = u.user_id and r.role_key in ('admin', 'employee') and r.del_flag = '0')
and u.user_id = #{userId}
order by u.user_id
